<body>
  <main class="wrap">
    <h1>Pocket Garden</h1>
    <p class="intro">Pick a plant, check how much light it likes, and mark what you have planted.</p>
    <p class="notice"><strong>Note:</strong> your choices (planted plants and the selected filter) reset when you reload this page.</p>

    <fieldset class="filters">
      <legend>Filter plants by light</legend>
      <div class="filter-row">
        <button type="button" data-filter="all" aria-pressed="true">All plants</button>
        <button type="button" data-filter="sun" aria-pressed="false">Loves sun</button>
        <button type="button" data-filter="shade" aria-pressed="false">Likes shade</button>
      </div>
    </fieldset>

    <p class="status" id="status" role="status" aria-live="polite"></p>

    <ul class="grid" id="grid">
      <li class="card" data-light="sun">
        <span class="icon" aria-hidden="true">🌿</span>
        <h2>Basil</h2>
        <span class="tag sun">Loves sun</span>
        <p>A fragrant herb that grows best with plenty of warm, bright light.</p>
        <button type="button" class="plant-btn" aria-pressed="false">
          <span class="label">Mark as planted</span><span class="sr-only">: Basil</span>
        </button>
      </li>

      <li class="card" data-light="sun">
        <span class="icon" aria-hidden="true">🌻</span>
        <h2>Sunflower</h2>
        <span class="tag sun">Loves sun</span>
        <p>Tall and cheerful, it follows the sun and wants a full, open spot.</p>
        <button type="button" class="plant-btn" aria-pressed="false">
          <span class="label">Mark as planted</span><span class="sr-only">: Sunflower</span>
        </button>
      </li>

      <li class="card" data-light="shade">
        <span class="icon" aria-hidden="true">🍃</span>
        <h2>Mint</h2>
        <span class="tag shade">Likes shade</span>
        <p>A hardy, fresh-smelling herb that is happy in cooler, shadier corners.</p>
        <button type="button" class="plant-btn" aria-pressed="false">
          <span class="label">Mark as planted</span><span class="sr-only">: Mint</span>
        </button>
      </li>
    </ul>
  </main>

<script>
  (function () {
    var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
    var filterButtons = Array.prototype.slice.call(document.querySelectorAll('[data-filter]'));
    var status = document.getElementById('status');
    var names = { all: 'all plants', sun: 'plants that love sun', shade: 'plants that like shade' };

    function applyFilter(filter) {
      var shown = 0;
      cards.forEach(function (card) {
        var match = filter === 'all' || card.dataset.light === filter;
        card.hidden = !match;
        if (match) shown++;
      });
      filterButtons.forEach(function (btn) {
        btn.setAttribute('aria-pressed', String(btn.dataset.filter === filter));
      });
      status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' — ' + names[filter] + '.';
    }

    filterButtons.forEach(function (btn) {
      btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
    });

    cards.forEach(function (card) {
      var btn = card.querySelector('.plant-btn');
      var label = btn.querySelector('.label');
      btn.addEventListener('click', function () {
        var planted = btn.getAttribute('aria-pressed') !== 'true';
        btn.setAttribute('aria-pressed', String(planted));
        label.textContent = planted ? 'Planted' : 'Mark as planted';
        card.classList.toggle('is-planted', planted);
      });
    });

    applyFilter('all');
  })();
</script>
